/*
 * validation driver for libopenaptx — ONE driver, three link targets
 * (c / c2rust_raw / ours). Calls only the C ABI that c2rust preserves.
 *
 * CLI:
 *   driver <op> <input> <iters>
 *     encode         : PCM -> aptX (standard), incl. aptx_encode_finish
 *     encode_hd      : PCM -> aptX HD
 *     decode         : aptX -> PCM (input generated by the C reference)
 *     decode_hd      : aptX HD -> PCM
 *     decode_sync    : auto-sync decode of a stream with a corrupted prefix
 *                      (Bluetooth packet-loss recovery path) + sync_finish
 *     reset_stream   : chunked encode with aptx_reset between chunks
 *   driver gen_pcm  <ignored> <out.pcm>      ~2MB 24-bit stereo test signal
 *                                            (multi-tone + sweep + transients)
 *   driver gen_aptx <in.pcm> <out.aptx>      encode with standard profile
 *   driver gen_aptxhd <in.pcm> <out.aptxhd>  encode with HD profile
 *
 * Output: ONE digest line on stdout (project convention).
 */
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "openaptx.h"

/* 4-lane xor-rotate digest (project convention) */
static inline uint64_t rotl64(uint64_t x, int r) { return (x << r) | (x >> (64 - r)); }

static uint64_t digest64(uint64_t seed, const uint8_t *p, size_t n) {
    uint64_t l0 = seed ^ 0xcbf29ce484222325ULL;
    uint64_t l1 = 0x84222325cbf29ce4ULL;
    uint64_t l2 = 0x9ce484222325cbf2ULL;
    uint64_t l3 = 0x2325cbf29ce48422ULL;
    size_t i = 0;
    for (; i + 32 <= n; i += 32) {
        uint64_t w0, w1, w2, w3;
        memcpy(&w0, p + i,      8);
        memcpy(&w1, p + i + 8,  8);
        memcpy(&w2, p + i + 16, 8);
        memcpy(&w3, p + i + 24, 8);
        l0 = rotl64(l0 ^ w0, 17);
        l1 = rotl64(l1 ^ w1, 19);
        l2 = rotl64(l2 ^ w2, 23);
        l3 = rotl64(l3 ^ w3, 29);
    }
    for (; i < n; i++)
        l0 = rotl64(l0 ^ p[i], 11);
    uint64_t h = l0 * 0x9e3779b97f4a7c15ULL;
    h ^= rotl64(l1, 1); h *= 0x9e3779b97f4a7c15ULL;
    h ^= rotl64(l2, 2); h *= 0x9e3779b97f4a7c15ULL;
    h ^= rotl64(l3, 3); h *= 0x9e3779b97f4a7c15ULL;
    return h;
}

static uint8_t *read_file(const char *path, size_t *out_n) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(2); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = malloc((size_t)n);
    if (!buf || fread(buf, 1, (size_t)n, f) != (size_t)n) {
        fprintf(stderr, "cannot read %s\n", path); exit(2);
    }
    fclose(f);
    *out_n = (size_t)n;
    return buf;
}

static void run_encode(const uint8_t *pcm, size_t n, long iters, int hd,
                       const char *op) {
    size_t cap = n + n / 2 + 4096;
    uint8_t *out = malloc(cap);
    if (!out) { fprintf(stderr, "oom\n"); exit(2); }
    uint64_t h = 0, total = 0;
    for (long i = 0; i < iters; i++) {
        struct aptx_context *ctx = aptx_init(hd);
        if (!ctx) { fprintf(stderr, "aptx_init failed\n"); exit(3); }
        size_t written = 0;
        size_t consumed = aptx_encode(ctx, pcm, n, out, cap, &written);
        uint64_t meta[2] = { consumed, written };
        h = digest64(h, out, written);
        size_t fin_written = 0;
        if (aptx_encode_finish(ctx, out, cap, &fin_written) && fin_written)
            h = digest64(h, out, fin_written);
        meta[1] += fin_written;
        h = digest64(h, (const uint8_t *)meta, sizeof(meta));
        total = meta[1];
        aptx_finish(ctx);
    }
    printf("op=%s in=%zu out=%llu iters=%ld digest=%016llx\n",
           op, n, (unsigned long long)total, iters, (unsigned long long)h);
    free(out);
}

static void run_decode(const uint8_t *ap, size_t n, long iters, int hd,
                       const char *op) {
    size_t cap = n * 8 + 4096;
    uint8_t *out = malloc(cap);
    if (!out) { fprintf(stderr, "oom\n"); exit(2); }
    uint64_t h = 0, total = 0;
    for (long i = 0; i < iters; i++) {
        struct aptx_context *ctx = aptx_init(hd);
        size_t written = 0;
        size_t consumed = aptx_decode(ctx, ap, n, out, cap, &written);
        if (consumed == 0) { fprintf(stderr, "decode consumed 0\n"); exit(3); }
        h = digest64(h, out, written);
        uint64_t meta[2] = { consumed, written };
        h = digest64(h, (const uint8_t *)meta, sizeof(meta));
        total = written;
        aptx_finish(ctx);
    }
    printf("op=%s in=%zu out=%llu iters=%ld digest=%016llx\n",
           op, n, (unsigned long long)total, iters, (unsigned long long)h);
    free(out);
}

/* corrupt the stream head, then let the auto-sync decoder recover */
static void run_decode_sync(const uint8_t *ap, size_t n, long iters) {
    if (n < 1024) { fprintf(stderr, "stream too short\n"); exit(2); }
    uint8_t *broken = malloc(n);
    memcpy(broken, ap, n);
    for (size_t k = 0; k < 37; k++) broken[k] ^= 0x5A;   /* head damage: initial sync */
    for (size_t k = n / 2; k < n / 2 + 53; k++) broken[k] ^= 0xA5;  /* mid-stream: re-sync */
    size_t cap = n * 8 + 4096;
    uint8_t *out = malloc(cap);
    if (!broken || !out) { fprintf(stderr, "oom\n"); exit(2); }
    uint64_t h = 0, total = 0;
    for (long i = 0; i < iters; i++) {
        struct aptx_context *ctx = aptx_init(0);
        size_t written = 0;
        int synced = 0;
        size_t dropped = 0;
        size_t consumed = aptx_decode_sync(ctx, broken, n, out, cap, &written,
                                           &synced, &dropped);
        h = digest64(h, out, written);
        uint64_t meta[4] = { consumed, written, (uint64_t)synced, dropped };
        h = digest64(h, (const uint8_t *)meta, sizeof(meta));
        size_t fdropped = aptx_decode_sync_finish(ctx);
        uint64_t fd = (uint64_t)fdropped;
        h = digest64(h, (const uint8_t *)&fd, sizeof(fd));
        total = written;
        aptx_finish(ctx);
    }
    printf("op=decode_sync in=%zu out=%llu iters=%ld digest=%016llx\n",
           n, (unsigned long long)total, iters, (unsigned long long)h);
    free(broken); free(out);
}

/* chunked encode with aptx_reset between chunks (stream restart path) */
static void run_reset_stream(const uint8_t *pcm, size_t n, long iters) {
    enum { CHUNK = 65536 * 3 };   /* multiple of the 24-byte frame */
    size_t cap = CHUNK * 2 + 4096;
    uint8_t *out = malloc(cap);
    if (!out) { fprintf(stderr, "oom\n"); exit(2); }
    uint64_t h = 0;
    for (long i = 0; i < iters; i++) {
        struct aptx_context *ctx = aptx_init(0);
        for (size_t off = 0; off + CHUNK <= n; off += CHUNK) {
            size_t written = 0;
            aptx_encode(ctx, pcm + off, CHUNK, out, cap, &written);
            h = digest64(h, out, written);
            aptx_reset(ctx);
        }
        aptx_finish(ctx);
    }
    printf("op=reset_stream in=%zu out=0 iters=%ld digest=%016llx\n",
           n, iters, (unsigned long long)h);
    free(out);
}

/* ~2MB 24-bit stereo test signal: tone mix + sweep + transients (standard
 * codec test material, fully deterministic) */
static void gen_pcm(const char *out_path) {
    enum { FRAMES = 350000 };     /* stereo frames, 6 bytes each -> ~2.1MB */
    FILE *f = fopen(out_path, "wb");
    if (!f) { fprintf(stderr, "cannot open %s\n", out_path); exit(2); }
    for (long i = 0; i < FRAMES; i++) {
        double t = (double)i / 44100.0;
        double sweep = 200.0 + 3000.0 * ((double)i / FRAMES);
        double l = 0.4 * sin(2 * M_PI * 440.0 * t)
                 + 0.25 * sin(2 * M_PI * 1000.0 * t)
                 + 0.2 * sin(2 * M_PI * sweep * t);
        double r = 0.4 * sin(2 * M_PI * 554.37 * t)
                 + 0.25 * sin(2 * M_PI * 1500.0 * t)
                 + 0.2 * sin(2 * M_PI * sweep * 1.5 * t);
        if ((i / 4410) % 10 == 9) { l *= 0.05; r *= 0.05; }   /* transients */
        int32_t ls = (int32_t)(l * 4000000.0);
        int32_t rs = (int32_t)(r * 4000000.0);
        uint8_t frame[6] = {
            (uint8_t)(ls & 0xff), (uint8_t)((ls >> 8) & 0xff), (uint8_t)((ls >> 16) & 0xff),
            (uint8_t)(rs & 0xff), (uint8_t)((rs >> 8) & 0xff), (uint8_t)((rs >> 16) & 0xff),
        };
        fwrite(frame, 1, 6, f);
    }
    fclose(f);
    fprintf(stderr, "wrote %s (%d stereo frames)\n", out_path, FRAMES);
}

static void gen_aptx(const char *in_path, const char *out_path, int hd) {
    size_t n;
    uint8_t *pcm = read_file(in_path, &n);
    size_t cap = n + n / 2 + 4096;
    uint8_t *out = malloc(cap);
    struct aptx_context *ctx = aptx_init(hd);
    size_t written = 0;
    aptx_encode(ctx, pcm, n, out, cap, &written);
    size_t fin = 0;
    FILE *f = fopen(out_path, "wb");
    fwrite(out, 1, written, f);
    if (aptx_encode_finish(ctx, out, cap, &fin) && fin) fwrite(out, 1, fin, f);
    fclose(f);
    aptx_finish(ctx);
    fprintf(stderr, "wrote %s (%zu bytes)\n", out_path, written + fin);
    free(pcm); free(out);
}

int main(int argc, char **argv) {
    if (argc == 4 && strcmp(argv[1], "gen_pcm") == 0)    { gen_pcm(argv[3]); return 0; }
    if (argc == 4 && strcmp(argv[1], "gen_aptx") == 0)   { gen_aptx(argv[2], argv[3], 0); return 0; }
    if (argc == 4 && strcmp(argv[1], "gen_aptxhd") == 0) { gen_aptx(argv[2], argv[3], 1); return 0; }
    if (argc != 4) {
        fprintf(stderr, "usage: %s <op> <input> <iters>\n", argv[0]);
        return 1;
    }
    const char *op = argv[1];
    long iters = strtol(argv[3], NULL, 10);
    if (iters <= 0) { fprintf(stderr, "bad iters\n"); return 1; }
    size_t n;
    uint8_t *buf = read_file(argv[2], &n);

    if (strcmp(op, "encode") == 0)            run_encode(buf, n, iters, 0, op);
    else if (strcmp(op, "encode_hd") == 0)    run_encode(buf, n, iters, 1, op);
    else if (strcmp(op, "decode") == 0)       run_decode(buf, n, iters, 0, op);
    else if (strcmp(op, "decode_hd") == 0)    run_decode(buf, n, iters, 1, op);
    else if (strcmp(op, "decode_sync") == 0)  run_decode_sync(buf, n, iters);
    else if (strcmp(op, "reset_stream") == 0) run_reset_stream(buf, n, iters);
    else { fprintf(stderr, "unknown op %s\n", op); return 1; }

    free(buf);
    return 0;
}
